<?php
use App\Core\{Auth,Database as DB};use App\Services\StudentService as S;
$courses=S::courses($student);$modules=[];$next=null;$done=0;$total=0;$seconds=0;$progressSum=0;
foreach($courses as $course){foreach($course['modules'] as $m){$modules[]=$m;foreach($m['lessons'] as $l){$total++;$progressSum+=$l['percent'];$done+=$l['completed']?1:0;$seconds+=$l['seconds'];if(!$next&&$course['enrolment_status']!=='completed'&&$l['unlocked']&&!$l['completed']){$next=$l+['subject_name'=>$course['name']];}}}}
$percent=$total?(int)round($progressSum/$total):0;$attendance=DB::one("SELECT COUNT(*) AS total,SUM(CASE status WHEN 'present' THEN 1 WHEN 'late' THEN 1 WHEN 'half_day' THEN 0.5 ELSE 0 END) AS attended FROM attendance_records WHERE user_id=? AND attendance_for='student' AND status<>'holiday'",[$student]);$attendancePercent=$attendance['total']?round((float)$attendance['attended']/(int)$attendance['total']*100).'%':'—';
$testRows=DB::all("SELECT t.id FROM tests t JOIN student_subjects ss ON ss.subject_id=t.subject_id JOIN subjects s ON s.id=t.subject_id WHERE ss.student_id=? AND ss.status='active' AND s.is_active=1 AND t.status='published' ORDER BY t.id",[$student]);if(\App\Services\AssignmentAccessService::forStudent($student)){$p=[];$w=\App\Services\AssignmentAccessService::subjectFilter('t.subject_id',$student,$p);$testRows=DB::all("SELECT t.id FROM tests t WHERE t.status='published' AND $w ORDER BY t.id",$p);}$availableTest=null;foreach($testRows as $row){$state=S::testState($student,(int)$row['id']);if($state&&$state['available']){$availableTest=$state;break;}}
page_header('Dashboard'); ?>
<section class="intro student-welcome"><h2><?= e(tr('Welcome back')) ?>, <?= e(explode(' ',preg_replace('/^Demo /','',Auth::user()['name']))[0]) ?> 👋</h2><p><?= e(tr('Keep learning, keep growing.')) ?></p></section>
<nav class="student-quick-nav" aria-label="<?= e(tr('Quick actions')) ?>"><?php foreach([['courses.php','My Courses','book'],['tests.php','Tests','test'],['progress.php','My Progress','chart'],['offline_downloads.php','Downloads','download']] as [$url,$label,$ico]): ?><a href="<?= e($url) ?>"><?= icon($ico) ?><span><?= e(tr($label)) ?></span><?= icon('arrow') ?></a><?php endforeach; ?></nav><div class="stats-grid"><?php foreach([['Overall progress',$percent.'%','chart'],['Study time',intdiv($seconds,3600).'h '.intdiv($seconds%3600,60).'m','clock'],['Completed lessons',$done.' / '.$total,'book'],['Attendance',$attendancePercent,'check']] as [$label,$value,$ico]): ?><div class="stat-card"><span class="stat-symbol"><?= icon($ico) ?></span><div><div class="stat-label"><?= e(tr($label)) ?></div><div class="stat-number"><?= e((string)$value) ?></div></div></div><?php endforeach; ?></div>
<div class="dashboard-columns"><section class="card"><div class="card-heading"><h2><?= e(tr('Continue Learning')) ?></h2><span class="pill ok"><?= $percent ?>% <?= e(tr('Completed')) ?></span></div><?php if($next): ?><div class="continue-row"><span class="continue-art"><?= icon('bolt') ?></span><div><h3><?= e($next['subject_name']) ?></h3><p class="muted"><?= e($next['title']) ?></p><div class="progress-track"><div class="progress-fill w<?= (int)$next['percent'] ?>"></div></div></div></div><a class="btn btn-primary full-width" href="lesson.php?id=<?= (int)$next['id'] ?>"><?= icon('play') ?><?= e(tr('Continue Learning')) ?></a><?php else: ?><div class="empty-state"><?= icon('check') ?><p><?= e(tr($courses?'Choose a course to review your learning.':'No courses assigned yet.')) ?></p><a class="btn" href="courses.php"><?= e(tr('My Courses')) ?></a></div><?php endif; ?></section>
<section class="card"><div class="card-heading"><h2><?= e(tr('Your next test')) ?></h2><?= icon('test') ?></div><?php if($availableTest): ?><h3><?= e($availableTest['localized_title']) ?></h3><p class="muted"><?= (int)$availableTest['duration_minutes'] ?> <?= e(tr('minutes')) ?> · <?= e(tr($availableTest['test_type'])) ?></p><a class="btn btn-primary full-width" href="tests.php?id=<?= (int)$availableTest['id'] ?>"><?= e(tr('Start test')) ?><?= icon('arrow') ?></a><?php else: ?><p class="muted"><?= e(tr('Complete your lessons to unlock the next test.')) ?></p><a class="btn" href="tests.php"><?= e(tr('Tests')) ?></a><?php endif; ?></section></div>
<section class="card" id="courses"><div class="card-heading"><h2><?= e(tr('My Courses')) ?></h2><a href="courses.php"><?= e(tr('View all')) ?> →</a></div><div class="course-grid"><?php foreach($courses as $course): require APP_ROOT.'/app/Views/student_course_card.php'; endforeach; ?></div><?php if(!$courses): ?><div class="empty-state"><?= icon('book') ?><h3><?= e(tr('No courses assigned yet.')) ?></h3><p><?= e(tr('Ask your Admin to assign your batch.')) ?></p></div><?php endif; ?></section>
<?php require APP_ROOT.'/app/Views/attendance_checkin.php';page_footer();
